insert into public.solutions (id, slug, title, eyebrow, summary, short, icon, tone, badge, stats, points, video, sort_order) values ('sol-revenue', 'revenue-automation', 'Revenue Automation', 'Solution · +45% AOV', 'AI-optimized pricing, upsells and abandoned cart recovery running around the clock, so every visitor sees the offer most likely to convert them.', 'Pricing, upsells and cart recovery — 24/7.', 'revenue', '#3B82F6', '+45% AOV', '[["Avg order value", "+45%"], ["Carts recovered", "1 in 3"], ["Setup time", "7–14 days"]]'::jsonb, '["Dynamic upsell and bundle logic based on cart contents", "Cart recovery sequences over email, SMS and WhatsApp", "Post-purchase offers triggered automatically", "Price testing that reports back what actually converts"]'::jsonb, '{}'::jsonb, '0') on conflict (id) do nothing;
insert into public.solutions (id, slug, title, eyebrow, summary, short, icon, tone, badge, stats, points, video, sort_order) values ('sol-fulfilment', 'order-fulfillment', 'Order Fulfillment', 'Solution · 0 manual work', 'From order to delivery — fulfillment, supplier routing, tracking and customer notifications handled end to end without a spreadsheet.', 'Order to delivery, hands off.', 'package', '#38BDF8', '0 manual work', '[["Time saved", "20 hrs/week"], ["Manual steps", "0"], ["Setup time", "7–14 days"]]'::jsonb, '["Orders routed to the right supplier automatically", "Tracking numbers pushed back to the customer", "Stock synced across every sales channel", "Exceptions flagged to your team with full context"]'::jsonb, '{}'::jsonb, '1') on conflict (id) do nothing;
insert into public.solutions (id, slug, title, eyebrow, summary, short, icon, tone, badge, stats, points, video, sort_order) values ('sol-social', 'social-media-growth', 'Social Media Growth', 'Solution · 10x followers', 'Auto-posting, engagement and content scheduling for Instagram and TikTok, timed to when your audience is actually online.', 'Auto-posting for Instagram and TikTok.', 'social', '#F472B6', '10x followers', '[["Follower growth", "up to 10x"], ["Posts/week", "14+"], ["Hours saved", "12/week"]]'::jsonb, '["AI captions and hashtags matched to each post", "Publishing at peak engagement windows", "Comment and DM replies handled automatically", "Monthly reporting on reach, saves and follows"]'::jsonb, '{}'::jsonb, '2') on conflict (id) do nothing;
