insert into public.solutions (id, slug, title, eyebrow, summary, short, icon, tone, badge, stats, points, video, sort_order) values ('sol-ads', 'ai-smart-ads', 'AI Smart Ads', 'Solution · 4.2x ROAS', 'Machine learning manages your Meta and Google campaigns — budget moves to what performs, daily, without you watching it.', 'ML-managed Meta and Google ads.', 'target', '#FBBF24', '4.2x ROAS', '[["Average ROAS", "4.2x"], ["Ad spend", "−35%"], ["Reporting", "Daily"]]'::jsonb, '["Budget reallocated to the best performing ad sets", "Creative testing on a fixed weekly cycle", "Audience building from your own store data", "Full funnel tracking from click to delivered order"]'::jsonb, '{}'::jsonb, '4') on conflict (id) do nothing;
insert into public.solutions (id, slug, title, eyebrow, summary, short, icon, tone, badge, stats, points, video, sort_order) values ('sol-support', 'ai-customer-support', 'AI Customer Support', 'Solution · 80% automated', 'A chatbot that answers 80% of questions instantly on WhatsApp and your website, and hands the rest to your team with the full conversation attached.', 'Instant replies on WhatsApp and your site.', 'bot', '#7C6CFF', '80% automated', '[["Questions handled", "80%"], ["First reply", "under 2s"], ["Languages", "Arabic + English"]]'::jsonb, '["Trained on your products, policies and order data", "Live order status lookups inside the chat", "Escalation to a human with full context", "Available every hour of every day"]'::jsonb, '{}'::jsonb, '5') on conflict (id) do nothing;
insert into public.goals (id, slug, title, eyebrow, summary, short, icon, tone, metric, "metricLabel", stats, points, video, sort_order) values ('goal-revenue', 'increase-revenue', 'Increase revenue', 'Goal', 'Lift what each customer spends without buying more traffic. Smart upsells, AI pricing and cart recovery do the work.', 'Upsells, AI pricing, cart recovery.', 'revenue', '#3B82F6', '+45%', 'average order value', '[["Avg order value", "+45%"], ["Revenue growth", "+132%"], ["Typical payback", "Month 1"]]'::jsonb, '["Start with a free audit of your current funnel", "We build upsell and recovery flows around your catalog", "You keep the system whether or not you continue with us"]'::jsonb, '{}'::jsonb, '0') on conflict (id) do nothing;
insert into public.goals (id, slug, title, eyebrow, summary, short, icon, tone, metric, "metricLabel", stats, points, video, sort_order) values ('goal-ops', 'automate-operations', 'Automate operations', 'Goal', 'Orders, fulfillment, tracking and supplier updates run end to end so your team stops copying data between tabs.', 'Orders and fulfillment on autopilot.', 'package', '#7C6CFF', '20hrs', 'saved every week', '[["Hours saved", "20/week"], ["Manual steps", "0"], ["Go live", "Under 14 days"]]'::jsonb, '["We map your current workflow before changing anything", "Automations plug into the tools you already use", "Everything is monitored, with alerts when something needs a human"]'::jsonb, '{}'::jsonb, '1') on conflict (id) do nothing;
