insert into public.systems (id, slug, title, eyebrow, summary, short, tag, stats, points, video, sort_order) values ('sys-accounting', 'accounting-system', 'Accounting System', 'Custom system · Finance', 'A centralized financial system that replaces spreadsheets and manual reconciliation with a single source of truth for revenue, costs and receivables. It runs the full cycle from quotation to collection: issuing invoices, recording payments across cash, bank transfer, card and COD, tracking outstanding balances per customer, and closing periods with a clear audit trail.', 'Invoicing, receivables and ETA e-invoicing.', 'Finance', '[["Compliance", "ETA e-invoicing"], ["Base currency", "EGP"], ["Access", "Role-based"]]'::jsonb, '["ETA e-invoicing compliance — Egyptian Tax Authority submission and status tracking", "Chart of accounts, journal entries and automated posting rules", "Customer and supplier ledgers with aging reports on receivables and payables", "Invoicing and credit notes in EGP, with multi-currency support where needed", "Expense capture with category and cost-center allocation", "VAT handling and tax reporting", "Role-based access so staff see only what their function requires", "Dashboards and exportable reports: P&L, cash position, collections, revenue by channel"]'::jsonb, '{}'::jsonb, '0') on conflict (id) do nothing;
insert into public.systems (id, slug, title, eyebrow, summary, short, tag, stats, points, video, sort_order) values ('sys-seo', 'seo-forge', 'SEO Forge', 'Custom system · AI + SEO', 'Keyword research, content generation, rank tracking and site audits, powered by AI.', 'Keywords, content and rank tracking.', 'AI + SEO', '[["Languages", "Arabic + English"], ["Tracking", "Daily"], ["Demo", "On request"]]'::jsonb, '["Keyword research with local search intent", "AI drafted content briefs and copy", "Daily rank tracking by keyword and page", "Technical site audits with prioritized fixes"]'::jsonb, '{}'::jsonb, '1') on conflict (id) do nothing;
insert into public.systems (id, slug, title, eyebrow, summary, short, tag, stats, points, video, sort_order) values ('sys-courier', 'courier-system', 'Courier System', 'Custom system · Logistics', 'An operations system covering the shipment lifecycle from pickup request to proof of delivery and cash settlement. It gives dispatch a live view of every order, gives couriers a mobile task list, and gives your customers automated status updates without manual follow-up.', 'Dispatch, COD settlement and proof of delivery.', 'Logistics', '[["COD settlement", "Daily"], ["Tracking", "Real time"], ["Notifications", "WhatsApp + SMS"]]'::jsonb, '["Order intake via dashboard, bulk upload or API from your sales channels", "Automated AWB generation and printable labels", "Zone and weight-based pricing rules with configurable rate cards", "Assignment and routing — shipments allocated to couriers by zone, capacity or manual override", "Courier mobile view for status updates, delivery attempts and proof of delivery (signature or photo)", "Real-time tracking page for end customers, plus WhatsApp and SMS status notifications", "Returns and failed-delivery handling with reattempt scheduling", "COD collection tracking per courier, with daily settlement and remittance reports", "Performance reporting: delivery success rate, average transit time, courier productivity, zone profitability"]'::jsonb, '{}'::jsonb, '2') on conflict (id) do nothing;
insert into public.systems (id, slug, title, eyebrow, summary, short, tagline, tag, stats, points, video, sort_order) values ('sys-analytics', 'google-analytics-system', 'Google Analytics System', 'Custom system · Analytics', 'Most businesses have one dashboard and half the answer. This is five tools wired together — traffic, behaviour, search and ads in one connected picture instead of five disconnected logins, so you can see who visited, what they clicked, where they dropped off, and what your ad spend actually returned.', 'GA4, Clarity, Search Console and Ads in one view.', 'Know exactly where every customer came from — and what they did next.', 'Analytics', '[["Tools connected", "5"], ["Reporting", "Day, week, month"], ["Setup", "No code changes"]]'::jsonb, '["Google Analytics 4 — how many visitors, where they came from, and how your traffic moves over time", "Google Tag Manager — the wiring: every tool connected and firing correctly, with no code changes", "Microsoft Clarity — session recordings and heatmaps showing how far each visitor scrolled, what they clicked, and where they gave up", "Google Search Console — which keywords you rank for, which pages perform, and which pages Google cannot reach", "Google Ads — paid campaigns running on the same data, so spend follows what is actually converting"]'::jsonb, '{}'::jsonb, '4') on conflict (id) do nothing;
insert into public.automations (id, slug, title, eyebrow, summary, tagline, icon, tone, stats, points, video, sort_order) values ('auto-whatsapp', 'whatsapp-ai-system', 'Smart Multi-Number WhatsApp Inbox', 'Automation', 'A unified, real-time inbox that connects many WhatsApp numbers into one screen, where AI tags every conversation, classifies intent and sentiment, and prioritizes the queue so your team manages by exception.', 'Organization is almost entirely AI-automated: the AI reads every incoming conversation and classifies it in real time, removing the manual triage work.', 'whatsapp', '#34D399', '[["Connection", "Cloud API or QR"], ["Sync", "Real time"], ["Triage", "AI automated"]]'::jsonb, '["Connects multiple WhatsApp business numbers into one dashboard — official Meta Cloud API numbers and QR-linked numbers, added in minutes", "Each number managed independently: connect, rename, enable, disable, or disconnect cleanly along with all of its conversations", "One unified inbox across every connected number, filtered instantly to all numbers at once or a single number", "Live two-way message sync, with delivery and read status tracked on every message", "Accurate unread tracking and full-text search across customers, phone numbers and message content", "A customer profile beside each chat — lifetime orders, lifetime value, notes and history", "Automatic tagging: the AI flags conversations as NEED HUMAN, records outcomes such as exchange happened, and categorizes customers on its own", "Intent and sentiment detection on every conversation — price, product, order, return, complaint or tracking, positive through angry, each with a confidence score", "Tag totals computed across all conversations rather than only those on screen, so urgent and VIP chats surface automatically"]'::jsonb, '{}'::jsonb, '1') on conflict (id) do nothing;
insert into public.automations (id, slug, title, eyebrow, summary, icon, tone, stats, points, video, hidden, sort_order) values ('auto-youtube', 'youtube-ai-generator', 'YouTube AI generator', 'Automation', 'Turns your product catalog and blog content into scripted, scheduled video output.', 'play', '#F472B6', '[["Output", "Weekly"], ["Input", "Your catalog"]]'::jsonb, '["Scripts generated from existing product content", "Titles, descriptions and tags optimized for search", "Scheduled publishing on a fixed cadence"]'::jsonb, '{}'::jsonb, true, '3') on conflict (id) do nothing;
insert into public.automations (id, slug, title, eyebrow, summary, tagline, icon, tone, stats, points, video, sort_order) values ('auto-chatbot', 'ecommerce-chatbot', 'E-commerce chatbot', 'Automation', 'An all-in-one, AI-powered platform that unifies customer messaging, order management, marketing and analytics into a single operations hub — turning conversations into orders, and data into decisions.', 'The AI agent replies instantly in natural Egyptian Arabic, around the clock, and resolves the majority of conversations without anyone on your team touching them.', 'bot', '#38BDF8', '[["Coverage", "24/7"], ["Language", "Egyptian Arabic"], ["Orders", "Live Shopify"]]'::jsonb, '["Omnichannel inbox — multiple WhatsApp numbers, Messenger and Instagram in one real-time screen, with delivery and read tracking, full-text search and rich customer profiles", "The AI classifies every conversation by intent and sentiment, applies operational tags such as NEED HUMAN or exchange happened, and pushes urgent and VIP customers to the top", "A 24/7 AI agent that replies instantly in natural Egyptian Arabic and carries the full sales conversation end to end", "Understands text, product photos and voice notes — identifies products from images and answers pricing, availability and policy questions from live store data", "Hands off to a person when a case genuinely needs one, with the conversation flagged and already in context", "Creates real Shopify orders from the conversation — product, size, address and payment collected and confirmed, with extra items added to the existing order instead of fragmenting into duplicates", "Deposits and payment-screenshot verification, exchanges, returns and order tracking, all applied by business rules", "WhatsApp broadcast campaigns — text or image-and-button templates, sent on demand or scheduled to targeted lists", "Campaign analytics through to revenue: sent, delivered, read and orders generated, attributed to purchases by discount code", "Real-time operations metrics — conversations handled, automation rate, response coverage and staff performance", "AI business analytics on demand: top products and categories customers ask for, most common questions, demand trends and tag insights", "Built for volume — automatic retries and a background worker that catches anything slipping through, plus per-channel on/off, staff assignment and role-based views"]'::jsonb, '{}'::jsonb, '4') on conflict (id) do nothing;
insert into public.automations (id, slug, title, eyebrow, summary, tagline, icon, tone, stats, points, video, sort_order) values ('auto-custom', 'custom-automations', 'Custom automations', 'Automation', 'If it happens more than twice a week and follows rules, it can be automated. Tell us the workflow.', 'Cash on delivery is where the losses are. The flow tells a returning customer from a first-time one, and asks the risky orders for a deposit before anything ships.', 'build', '#7C6CFF', '[["Confirmation", "Automatic, 24/7"], ["Delivery slot", "Customer picks"], ["Languages", "Arabic or English"]]'::jsonb, '["Order confirmation flow — every new order confirmed on WhatsApp instantly, around the clock, with no agent making a call", "The customer books their own delivery slot inside the chat: date, time and location", "Returning customers get a smooth, friction-free confirmation, while risky first-time COD orders outside your delivery zone are asked for a deposit before the order ships", "Lower return rates — fewer packages coming back unopened, and no shipping paid twice", "Faster deliveries, because you already know when and where the customer wants it", "Fewer staff hours: no confirmation calls, no back-and-forth, no manual follow-up", "Instant replies in Arabic or English, on the app your customers already use", "Every order, every reply and every delivery slot recorded and reportable", "We map the workflow before building anything", "Built on the tools you already pay for", "Documented and handed over, not locked in"]'::jsonb, '{}'::jsonb, '5') on conflict (id) do nothing;
