insert into public.projects (id, slug, title, badge, short, summary, url, accent, theme, points, sort_order) values ('p-montre', 'montre-co', 'Montre Co.', 'Luxury Watches & Timepieces', 'Full Shopify store build, custom watch customizer and checkout UX.', 'Complete e-commerce store build for a luxury timepiece brand. Features custom automatic/chronograph watch showcases, interactive size selectors, high-converting checkout flows, and seamless mobile responsiveness.', 'https://montre-co.com/', '#3B82F6', 'montre', '["Shopify custom theme development", "Product filtering (Automatic, Chronograph, Diver, Dress)", "Speed and conversion rate optimization (CRO)", "Integrated automated order fulfillment and tracking"]'::jsonb, '0') on conflict (id) do nothing;
