insert into public.projects (id, slug, title, badge, short, summary, url, before_url, accent, theme, tagline, points, sort_order) values ('p-hollywood', 'hollywood-clinics', 'Hollywood Clinics', 'Healthcare & Services', 'Modern clinic platform, online booking and UI redesign.', 'Complete digital transformation for a multi-specialty clinic network. Upgraded from an outdated legacy platform to a modern, responsive website featuring seamless appointment booking, doctor profiles, service showcases, and fast mobile performance.', 'https://hollywoodclinics.net/', 'https://website.hollywood-clinics.com/', '#0E7C7B', 'clinic', 'Transforming healthcare accessibility with a modern, patient-first web experience.', '["Complete website redesign and modern UI/UX implementation", "Online appointment and booking system setup", "Doctors and specialties directory structure", "Mobile-first optimisation and page speed enhancement", "Arabic and multi-language support integration"]'::jsonb, '2') on conflict (id) do nothing;
